function roleSummary(){const f=roleFocus();return `<section class="role-summary" aria-label="Role focus"><span class="role-summary-label">YOUR WORKSPACE</span><strong>${f.title}</strong><p>${esc(f.detail)}</p><p class="role-access">${f.access}</p>${btn(f.label,f.action,'arrow','role-next')}</section>`;}
function pageInformation(){if(S.page==='explore')return 'Procurement renewals · Shared definitions and source evidence';if(S.page==='catalog'&&S.dcView)return S.dcView==='Data sources'?'Enterprise catalog · Registered source metadata':'Business semantics · Datasets, relationships and counting rules';if(window.FFLifecycleUI.pages[S.page])return window.FFLifecycleUI.subtitle();const assets=R.assets(),a=R.getAsset(S.selectedAsset),changes=R.changes().length;const readable=R.can('data');return ({catalog:`enterprise · ${assetRows().length} matching assets · ${assets.filter(a=>!a.owner).length} awaiting an owner`,dataset:`enterprise.${a?.domain}.${a?.name} · ${a?.rows?.toLocaleString()||0} records · ${readable?'Source records are read-only':'Schema access; record values restricted'}`,resource:`enterprise / ${a?.domain} / ${a?.type} · ${R.rawAccess(a)?'Records and metadata available':'Metadata access only'}`,objects:`Procurement ontology · 8 properties · ${readable?'2,408 objects':'Definition access'}${S.branch!=='main'?` · ${changes} branch ${changes===1?'change':'changes'}`:''}`,governance:`enterprise · ${assets.length} visible assets · ${R.can('maintain')?'Ownership and quality can be maintained':'Governance summary'}`,evaluations:`Supplier renewal v2.1 · 64 checks · ${R.can('evaluate')?'Validate the selected branch':'Results and coverage are read-only'}`,workflows:S.tab==='Reviews'?`Decision history · ${R.state.decisions.length} recorded · ${R.can('review')?'Business review available':'Decision summary'}`:S.selectedRun==='RUN-0248'?`Historical run on main · ${R.can('review')?'Review the source before approving':'Execution and business approval are separate'}`:`Sandbox result · ${R.can('operate')?'Review the outcome before continuing':'Outcome summary'}`,operations:'14-day usage · 4 models · 4 business workflows · model-call costs only'})[S.page]||'';}
function safeRoleContext(){const a=R.getAsset(S.selectedAsset);let message='';if(!a&&['dataset','resource'].includes(S.page)){navigate('catalog');S.selectedAsset='supplier_master';message='The previous asset is outside this role’s data scope.';}
if(!R.can('data')){if(S.page==='objects'&&['Overview','Objects'].includes(S.tab)){S.tab='Definition';message='Definition view is available; object records require data access.';}else if(['Sample data','Records'].includes(S.tab)){S.tab='Overview';message='Showing metadata; source records require data access.';}S.drawer=false;S.runTab='Details';}
return message;}

