 const navHTML=nav().replace(/^<aside class="sidebar">|<\/aside>$/g,'')+roleSummary(),sidebar=app.querySelector('.sidebar');if(sidebar._renderedHTML!==navHTML){const scroll=sidebar.scrollTop;sidebar.innerHTML=navHTML;sidebar._renderedHTML=navHTML;sidebar.scrollTop=scroll;}
 const pageHTML=S.page==='explore'?window.FFDiscoveryUI.explore():window.FFLifecycleUI.pages[S.page]?window.FFLifecycleUI.render():({catalog,dataset,resource,objects,governance,workflows,evaluations,operations})[S.page](),fragment=document.createElement('template');fragment.innerHTML=pageHTML;
