 const menu=app.querySelector('.role-menu-slot'),menuHTML=rolePopover();if(menu._renderedHTML!==menuHTML){menu.innerHTML=menuHTML;menu._renderedHTML=menuHTML;}
 if(id&&!window.FFShowcasePlayback){const el=document.getElementById(id);if(el){el.focus({preventScroll:true});if(typeof start==='number'&&el.setSelectionRange)el.setSelectionRange(start,start)}}else if(actionFocus&&!window.FFShowcasePlayback&&active!==document.activeElement){[...app.querySelectorAll('[data-action]')].find(el=>el.dataset.action===actionFocus)?.focus({preventScroll:true});}
