window.ForflowWorkbench={get state(){return JSON.parse(JSON.stringify(S))},initial,action,set(p){S={...S,...p};render()},reset(){if(film){R.reset();window.FFLifecycle.reset();}window.FFMotion.reset();S=initial();render()},film(v){film=v;document.body.classList.toggle('film',v)},render,motionTime:ms=>window.FFMotion.seek(ms),assetRows,filteredSuppliers};render();restoreRoute();

